kind: Job
metadata:
  name: {{ include "stateful-app.fullname" . }}-migrate
  labels:
    {{- include "stateful-app.labels" . | nindent 4 }}
  annotations:
    "helm.sh/hook": {{ include "stateful-app.migrationHook" . | quote }}
    "helm.sh/hook-weight": "0"
    "helm.sh/hook-delete-policy": before-hook-creation,hook-succeeded
    {{- with .Values.migration.annotations }}
    {{- toYaml . | nindent 4 }}
    {{- end }}
spec:
  backoffLimit: {{ .Values.migration.backoffLimit }}
  activeDeadlineSeconds: {{ .Values.migration.activeDeadlineSeconds }}
  template:
    metadata:
      labels:
        {{- include "stateful-app.selectorLabels" . | nindent 8 }}
        job-name: {{ include "stateful-app.fullname" . }}-migrate
        {{- with .Values.migration.podLabels }}
        {{- toYaml . | nindent 8 }}
        {{- end }}
      annotations:
        {{- with .Values.migration.podAnnotations }}
        {{- toYaml . | nindent 8 }}
        {{- end }}
        {{- if .Values.database.createSecret }}
        checksum/database-secret: {{ include (print $.Template.BasePath "/secret-db.yaml") . | sha256sum }}
        {{- end }}
    spec:
      serviceAccountName: {{ include "stateful-app.serviceAccountName" . }}
      restartPolicy: OnFailure
      {{- with .Values.imagePullSecrets }}
      imagePullSecrets:
        {{- toYaml . | nindent 8 }}
      {{- end }}
      securityContext:
        {{- toYaml .Values.podSecurityContext | nindent 8 }}
      containers:
        - name: migrate
          image: "{{ if .Values.migration.image.repository }}{{ .Values.migration.image.repository }}{{ else }}{{ .Values.image.repository }}{{ end }}:{{ if .Values.migration.image.tag }}{{ .Values.migration.image.tag }}{{ else }}{{ .Values.image.tag }}{{ end }}"
          imagePullPolicy: {{ if .Values.migration.image.pullPolicy }}{{ .Values.migration.image.pullPolicy }}{{ else }}{{ .Values.image.pullPolicy }}{{ end }}
          securityContext:
            {{- toYaml .Values.securityContext | nindent 12 }}
          command:
            {{- toYaml .Values.migration.command | nindent 12 }}
          args:
            {{- toYaml .Values.migration.args | nindent 12 }}
          env:
            {{- range .Values.migration.env }}
            - {{ toYaml . | nindent 14 | trim }}
            {{- end }}
            {{- if or .Values.database.createSecret .Values.database.existingSecret }}
            - name: {{ .Values.database.envName }}
              valueFrom:
                secretKeyRef:
                  name: {{ default (include "stateful-app.dbSecretName" .) .Values.database.existingSecret }}
                  key: {{ .Values.database.secretKey }}
            {{- end }}
          resources:
            {{- toYaml .Values.migration.resources | nindent 12 }}
  ttlSecondsAfterFinished: {{ .Values.migration.ttlSecondsAfterFinished }}
{{- end }}
---
# FILE: templates/pdb.yaml
{{- if .Values.pdb.enabled }}
apiVersion: policy/v1
kind: PodDisruptionBudget
metadata:
  name: {{ include "stateful-app.fullname" . }}
  labels:
    {{- include "stateful-app.labels" . | nindent 4 }}
spec:
  minAvailable: {{ .Values.pdb.minAvailable }}
  selector:
    matchLabels:
      {{- include "stateful-app.selectorLabels" . | nindent 6 }}
{{- end }}
---
# FILE: templates/networkpolicy.yaml
{{- if .Values.networkPolicy.enabled }}
apiVersion: networking.k8s.io/v1
kind: NetworkPolicy
metadata:
  name: {{ include "stateful-app.fullname" . }}
  labels:
    {{- include "stateful-app.labels" . | nindent 4 }}
spec:
  podSelector:
    matchLabels:
      {{- include "stateful-app.selectorLabels" . | nindent 6 }}
  policyTypes:
    - Ingress
    - Egress
  ingress:
    {{- if .Values.networkPolicy.allowSameNamespace }}
    - from:
        - podSelector: {}
    {{- else }}
    - {}
    {{- end }}
    {{- with .Values.networkPolicy.extraIngress }}
    {{- toYaml . | nindent 4 }}
    {{- end }}
  egress:
    {{- if .Values.networkPolicy.allowDNS }}
    - to:
        - namespaceSelector: {}
          podSelector:
            matchLabels:
              k8s-app: kube-dns
      ports:
        - protocol: UDP
          port: 53
        - protocol: TCP
          port: 53
    {{- end }}
    {{- with .Values.networkPolicy.extraEgress }}
    {{- toYaml . | nindent 4 }}
    {{- end }}
{{- end }}
